const input = $input.first().json;
const headers = input.headers ?? {};
const received = typeof headers['x-automation-signature'] === 'string'
  ? headers['x-automation-signature'].trim().toLowerCase()
  : '';
const digest = typeof input.expected_signature === 'string'
  ? input.expected_signature.toLowerCase()
  : '';
const expected = `sha256=${digest}`;
const signatureFormatValid = /^sha256=[a-f0-9]{64}$/.test(received) && /^sha256=[a-f0-9]{64}$/.test(expected);
let signatureMismatch = 1;
if (signatureFormatValid) {
  signatureMismatch = 0;
  for (let index = 0; index < expected.length; index += 1) {
    signatureMismatch |= expected.charCodeAt(index) ^ received.charCodeAt(index);
  }
}
const body = input.body ?? {};
const sentAt = body.sent_at;
const now = Math.floor(Date.now() / 1000);
const timestampValid = Number.isInteger(sentAt) && sentAt >= now - 300 && sentAt <= now + 60;
const eventId = typeof body.event_id === 'string' ? body.event_id : '';
const eventIdValid = /^evt_[A-Za-z0-9-]{8,64}$/.test(eventId);
const contentType = typeof headers['content-type'] === 'string' ? headers['content-type'].toLowerCase() : '';
const contentTypeValid = contentType.startsWith('application/json');
const signatureValid = signatureFormatValid && signatureMismatch === 0;
return [{ json: {
  accepted: signatureValid && timestampValid && eventIdValid && contentTypeValid,
  event_id: eventIdValid ? eventId : null,
  authenticated: signatureValid,
  fresh: timestampValid,
  age_seconds: Number.isInteger(sentAt) ? now - sentAt : null,
  replay_window_seconds: 300
} }];
